def grid_from_patterns(patterns):
    H=sum(len(p) for p in patterns)+len(patterns)+1
    W=max(len(p[0]) for p in patterns)+2
    g=[[0]*W for _ in range(H)]; r0=1
    for p in patterns:
        for i,row in enumerate(p):
            for j,v in enumerate(row):g[r0+i][1+j]=v
        r0+=len(p)+1
    return g

